import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
// นำเข้า CSS ตรงนี้เลย จะได้ไม่ต้องไปแก้ไฟล์อื่น
import 'chartist/dist/chartist.min.css'; 

import {
  Container,
  Row,
  Col,
  Card,
} from "react-bootstrap";

function Dashboard() {
  const [chartData, setChartData] = useState({
    labels: [],
    series: [] 
  });

  // ฟังก์ชันดึงข้อมูล
  const fetchData = async () => {
    try {
      const response = await fetch('http://localhost:3001/api/chart-data');
      const result = await response.json();

      console.log("Check Data:", result); // ดูค่าใน Console

      if (result && result.series) {
        setChartData(result);
      }
    } catch (error) {
      console.error("Fetch Error:", error);
    }
  };

  useEffect(() => {
    fetchData(); 
    const interval = setInterval(fetchData, 5000); 
    return () => clearInterval(interval);
  }, []);

  // --- ตั้งค่ากราฟ (Safe Mode) ---
  const options = {
    // ใช้ true เฉยๆ แทนคำสั่ง Interpolation ที่ทำให้ error
    lineSmooth: true, 
    low: 0,
    high: 30, // ปรับความสูงกราฟตรงนี้
    showArea: false,
    height: "245px",
    axisX: {
      showGrid: false,
    },
    showLine: true,
    showPoint: true,
    fullWidth: true,
    chartPadding: {
      right: 50
    }
  };

  const responsiveOptions = [
    ["screen and (max-width: 640px)", {
      axisX: {
        labelInterpolationFnc: function (value) {
          return value[0];
        }
      }
    }]
  ];

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card>
            <Card.Header>
              <Card.Title as="h4">Passenger Density</Card.Title>
              <p className="card-category">ข้อมูลจำนวนผู้โดยสาร (Real-time)</p>
            </Card.Header>
            <Card.Body>
              <div className="ct-chart" id="chartHours">
                {/* ถ้ามีข้อมูลให้โชว์กราฟ ถ้าไม่มีให้โชว์ Loading */}
                {chartData.series.length > 0 ? (
                  <ChartistGraph
                    data={chartData}
                    type="Line"
                    options={options}
                    responsiveOptions={responsiveOptions}
                  />
                ) : (
                  <div className="text-center p-3">
                    <p>... กำลังโหลดข้อมูล ...</p>
                    <small className="text-muted">
                        (ถ้าค้างหน้านี้นาน ให้เช็คว่าเปิดไฟล์ server.js หรือยัง)
                    </small>
                  </div>
                )}
              </div>
            </Card.Body>
            <Card.Footer>
              <div className="legend">
                <i className="fas fa-circle text-info"></i> ป้าย 1 (ฟ้า) &nbsp;
                <i className="fas fa-circle text-danger"></i> ป้าย 2 (แดง) &nbsp;
                <i className="fas fa-circle text-warning"></i> ป้าย 3 (ส้ม) &nbsp;
                <i className="fas fa-circle" style={{color: '#9368E9'}}></i> ป้าย 4 (ม่วง)
              </div>
            </Card.Footer>
          </Card>
        </Col>
      </Row>
    </Container>
  );
}

export default Dashboard;
